var DTMAP={'\ud83c\udf82':'cake','\ud83c\udf75':'drink','\ud83c\udf3f':'leaf','\ud83d\udc36':'dog','\ud83d\udc31':'cat','\ud83d\udc68\u200d\ud83d\udc69\u200d\ud83d\udc67':'family','\u2605':'other','\ud83e\uddf3':'arr','\u2708\ufe0f':'dep','\u2708':'dep'};
var DTRE=/(\ud83c\udf82|\ud83c\udf75|\ud83c\udf3f|\ud83d\udc36|\ud83d\udc31|\ud83d\udc68\u200d\ud83d\udc69\u200d\ud83d\udc67|\u2605|\ud83e\uddf3|\u2708\ufe0f?)/;
function dtiSwap(root){
  var list=[],w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,null);
  while(w.nextNode()){var n=w.currentNode;if(!DTRE.test(n.nodeValue))continue;var p=n.parentNode;
    if(p&&p.closest&&p.closest('textarea,input,option,script,style,.dti,[contenteditable="true"]'))continue;list.push(n)}
  list.forEach(function(n){
    var fr=document.createDocumentFragment();
    n.nodeValue.split(DTRE).forEach(function(part){
      if(!part)return;var k=DTMAP[part];
      if(k){var s=document.createElement('span');s.className='dti';s.innerHTML=DTI[k];fr.appendChild(s)}
      else fr.appendChild(document.createTextNode(part));
    });
    n.parentNode.replaceChild(fr,n);
  });
}
