var dRec=null,dListening=false,dMsgT=null;
function dMsg(t){var e=document.getElementById('dmsg');if(!e)return;e.textContent=t;clearTimeout(dMsgT);dMsgT=setTimeout(function(){var x=document.getElementById('dmsg');if(x)x.textContent=''},5000)}
function dMic(){
  var SR=window.SpeechRecognition||window.webkitSpeechRecognition,ta=document.getElementById('dtxa'),b=document.getElementById('dmic');
  if(!ta||!b)return;
  if(dListening&&dRec){try{dRec.stop()}catch(e){}return}
  if(!SR){dMsg('La dict\u00e9e vocale n\u2019est pas disponible dans ce navigateur. Utilise le micro du clavier.');return}
  var base=ta.value,fin='',r=new SR();
  r.lang='fr-FR';r.interimResults=true;r.continuous=true;
  r.onresult=function(e){
    if(!document.body.contains(ta)){try{r.stop()}catch(x){}return}
    var interim='';
    for(var i=e.resultIndex;i<e.results.length;i++){var tr=e.results[i][0].transcript;if(e.results[i].isFinal)fin+=tr;else interim+=tr}
    var sep=(base&&!/\s$/.test(base))?' ':'';
    ta.value=base+sep+fin+interim;
    dtxt('t',ta.value);
  };
  r.onerror=function(e){
    dListening=false;b.classList.remove('on');
    dMsg(e.error==='not-allowed'||e.error==='service-not-allowed'?'Le micro est bloqu\u00e9. Autorise-le dans les r\u00e9glages du navigateur, ou utilise le micro du clavier.':(e.error==='no-speech'?'Je n\u2019ai rien entendu.':'La dict\u00e9e s\u2019est arr\u00eat\u00e9e.'));
  };
  r.onend=function(){dListening=false;var x=document.getElementById('dmic');if(x)x.classList.remove('on')};
  dRec=r;
  try{r.start();dListening=true;b.classList.add('on');dMsg('Je t\u2019\u00e9coute\u2026 touche le micro pour arr\u00eater.')}catch(e){dMsg('Impossible de d\u00e9marrer le micro.')}
}
