  +'.dsm3{padding:12px 12px 10px;border-radius:22px;background:linear-gradient(135deg,#f9f8f6,#f9f8f6);border:1px solid #e8ced1;box-shadow:0 10px 20px -18px rgba(137,90,100,.6)}'
  +'.dsm3 .dsm-l{margin:0 0 7px;font-size:10px}'
