  +'.d3r{display:flex;justify-content:space-around;gap:6px;margin-top:11px;padding-top:10px;border-top:1px solid #e8ced1}.d3r>div{display:flex;flex-direction:column;align-items:center;gap:4px;cursor:pointer;min-width:0}'
  +'.d3c{width:40px;height:40px;border-radius:50%;overflow:hidden;background:#fff;border:2px solid #fff;box-shadow:0 5px 9px -7px rgba(137,90,100,.7);display:flex;align-items:center;justify-content:center}.d3c svg{width:100%;height:100%;display:block}.d3c.off svg{filter:saturate(.25);opacity:.55}.d3c.e{border:1.5px dashed #d9b0b6;background:rgba(255,255,255,.4);box-shadow:none;color:#c48f97;font-size:20px;line-height:1}'
  +'.d3r small{font-size:8.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);max-width:70px;text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}'
  +'.d3o{margin-top:11px;padding-top:10px;border-top:1px solid #e8ced1}.d3o .dsm-r{margin-top:0;gap:6px}.d3o .dsm-a{width:32px;height:32px}.d3o .dsm-a img{width:80%;height:80%}.d3o .ds-none{font-size:12px}'
  +'.dgr3{margin-top:10px;padding:11px 12px 10px;border-radius:22px;background:rgba(255,255,255,.65);border:1px solid #f3e7e7}.dgr3 .dsm-l{margin:0 0 6px;font-size:10px}'
  +'.dgr3 textarea{display:block;width:100%;box-sizing:border-box;min-height:84px;resize:none;border:0;background:repeating-linear-gradient(transparent,transparent 25px,#f3e7e7 25px,#f3e7e7 26px);padding:0 2px;font-family:"Lora",Georgia,serif;font-style:italic;font-size:15px;line-height:26px;color:var(--text);outline:none}'
  +'.mdg{display:flex;flex-wrap:wrap;justify-content:center;gap:16px 12px;margin:2px 0 6px}.mdb{width:84px;border:0;background:none;display:flex;flex-direction:column;align-items:center;gap:6px;padding:0;cursor:pointer;font:inherit}.mdb svg{width:60px;height:60px;border-radius:50%;background:radial-gradient(circle at 32% 26%,#fff,#f3e7e7 60%,#e7e3e0);box-shadow:0 6px 10px -7px rgba(137,90,100,.6)}.mdb small{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}.mdb.sel svg{box-shadow:0 0 0 4px #e8ced1,0 8px 12px -7px rgba(137,90,100,.7)}.mdb.sel small{color:#ac727e;font-weight:600}'
